INSERT INTO ntss.mst_coop_layout (ctl_no, facility_cd, coop_cd, coop_cd_index, direction, coop_cd_sub, coop_format, coop_name, coop_vender, description, is_editable, coop_setting, coop_ext_setting, is_disp, is_del, user_id, reg_date, up_date, coop_version) VALUES (-1030003, 'nkknkk', 'profile', '', 'R', 'all', 'xml', '日機装標準', 'nikkiso', '患者情報（XML)', '1', e'<Data Type="PatientInfo">
    <CRUD>col:$journal.const.crud,const:C</CRUD>
    <PatientId>col:$journal.pat_personal_main.hosp_pat_id</PatientId>
    <PatientNameKana>col:$journal.pat_personal_main.pat_name_kana</PatientNameKana>
    <PatientName>col:$journal.pat_personal_main.pat_name</PatientName>
    <Sex>col:$journal.pat_personal_main.pat_sex</Sex>
    <Birthday>col:$journal.pat_personal_main.pat_birthday</Birthday>
    <DialysisStartDate>col:$journal.pat_main.medical_care_info.dialysis_start_date</DialysisStartDate>
    <BodyInfo>
        <BloodABO>col:$journal.pat_personal_main.pat_blood_type_abo</BloodABO>
        <BloodRH>col:$journal.pat_personal_main.pat_blood_type_rh</BloodRH>
        <Height>
            <Value>col:$journal.detail.pat_unique.physical_info.height</Value>
            <DateTime>col:$journal.detail.pat_unique.physical_info.exam_height_date</DateTime>
        </Height>
        <Weight>
            <Value></Value>
            <!-- 連携対象外 -->
            <DateTime></DateTime>
            <!-- 連携対象外 -->
        </Weight>
        <CTR>
            <CTRValue>col:$journal.detail.pat_unique.physical_info.ctr</CTRValue>
            <HeartValue>col:$journal.detail.pat_unique.physical_info.breast_dia</HeartValue>
            <ThoraxValue>col:$journal.detail.pat_unique.physical_info.chest_dia</ThoraxValue>
            <DateTime>col:$journal.detail.pat_unique.physical_info.exam_CTR_date</DateTime>
        </CTR>
    </BodyInfo>
    <StaffInfo>
        <Doctor detail="担当医情報,Code"/>
        <Nurse detail="担当スタッフ情報,Code"/>
    </StaffInfo>
    <DialysisIndicatorInfo>
        <Department Code="col:$journal.pat_main.medical_care_info.main_course_cd_2">
            col:$journal.pat_main.medical_care_info.main_course_name_2
        </Department>
        <!-- 連携設定[指示医の取込フラグ]が"0"を設定したの場合、Doctorの設定を取り込まない-->
        <!-- Doctor Code="col:$journal.detail.pat_main.charge_staff_info.staff_cd" -->
        <Doctor Code="col:$journal.pat_main.charge_staff_info.indicator_staff_cd">
            col:$journal.pat_main.charge_staff_info.indicator_staff_name
        </Doctor>
    </DialysisIndicatorInfo>
    <HospitalizationInfo>
        <InOut>col:$journal.pat_personal_main.in_out_class</InOut>
        <!-- 連携設定[入院中診療科の取込フラグ]が"0"を設定したの場合、Departmentの設定を取り込まない-->
        <Department Code="col:$journal.pat_main.medical_care_info.main_course_cd">
            col:$journal.pat_main.medical_care_info.main_course_name
        </Department>
        <!-- Department Code="" -->
        <Ward Code="col:$journal.pat_main.medical_care_info.ward_cd">col:$journal.pat_main.medical_care_info.ward_name
        </Ward>
    </HospitalizationInfo>
    <ContactList>
        <Contact detail="住所詳細,SEQ"/>
    </ContactList>
    <DetailInfoList>
        <DetailInfo detail="詳細項目,Function"/>
